import uuid
from datetime import UTC, datetime
from typing import Any

from pydantic import BaseModel, Field


def utcnow() -> datetime:
    return datetime.now(UTC)


class RouteInfo(BaseModel):
    """Cataloged API endpoint information generated by Application Mapper Agent."""

    path: str
    method: str
    handler_name: str
    summary: str = ""
    auth_required: bool = False
    admin_only: bool = False
    parameters: list[str] = Field(default_factory=list)
    tags: list[str] = Field(default_factory=list)


class ModelInfo(BaseModel):
    """Discovered database entity model information."""

    model_name: str
    table_name: str
    fields: list[str] = Field(default_factory=list)


class ApplicationMap(BaseModel):
    """Complete application architecture inventory generated by Application Mapper."""

    app_name: str
    version: str
    scanned_at: datetime = Field(default_factory=utcnow)
    total_endpoints: int = 0
    endpoints: list[RouteInfo] = Field(default_factory=list)
    models: list[ModelInfo] = Field(default_factory=list)
    auth_flows: dict[str, Any] = Field(default_factory=dict)


class SecurityFinding(BaseModel):
    """Standardized finding record produced by pre-deployment security agents."""

    finding_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    agent_source: str
    category: str
    cwe_id: str
    owasp_category: str
    severity: str
    confidence: float
    title: str
    description: str
    file_path: str
    line_number: int | None = None
    endpoint: str | None = None
    method: str | None = None
    parameter: str | None = None
    raw_evidence: dict[str, Any] = Field(default_factory=dict)
    remediation_guidance: str
    status: str = "OPEN"
    created_at: datetime = Field(default_factory=utcnow)


class StaticScanReport(BaseModel):
    """Aggregated report of pre-deployment static analysis findings."""

    scan_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    timestamp: datetime = Field(default_factory=utcnow)
    total_findings: int = 0
    findings_by_severity: dict[str, int] = Field(default_factory=dict)
    findings_by_category: dict[str, int] = Field(default_factory=dict)
    findings: list[SecurityFinding] = Field(default_factory=list)
    application_map: ApplicationMap | None = None


class ProbeResult(BaseModel):
    """Result of an individual dynamic API probe."""

    probe_name: str
    target_endpoint: str
    target_method: str
    vulnerable: bool
    evidence: dict[str, Any] = Field(default_factory=dict)
    finding: SecurityFinding | None = None
    executed_at: datetime = Field(default_factory=utcnow)


class DynamicScanReport(BaseModel):
    """Comprehensive DAST and API security assessment report."""

    scan_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    timestamp: datetime = Field(default_factory=utcnow)
    probes_executed: int = 0
    vulnerabilities_confirmed: int = 0
    probes: list[ProbeResult] = Field(default_factory=list)
    findings: list[SecurityFinding] = Field(default_factory=list)
    confirmed_sast_count: int = 0
    openapi_conformance_status: str = "PASSED"
    openapi_issues: list[dict[str, Any]] = Field(default_factory=list)

